"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8898"],{45666(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.impedimento_mensagem_invalida","status":422,"titulo":"A mensagem do impedimento \xe9 obrigat\xf3ria e limitada"},"descricao":{"codigo":"uniplus.item_formulario.impedimento_mensagem_invalida","requisitos":[],"oQueAconteceu":["O impedimento de um item declara a mensagem que o candidato l\xea quando a resposta dele impede a inscri\xe7\xe3o. A `mensagem` do `impedimento` est\xe1 ausente, vazia, s\xf3 com espa\xe7os, tem mais de 500 caracteres depois de aparada ou cont\xe9m o caractere nulo. A mensagem \xe9 \\"A mensagem que explica o impedimento ao candidato \xe9 obrigat\xf3ria e tem no m\xe1ximo 500 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].impedimento.mensagem` ou, no campo de um grupo, `grupos[g].subitens[j].impedimento.mensagem`; nos modelos de formul\xe1rio come\xe7a por `conteudo.`. Nada \xe9 gravado. No campo de um grupo repet\xedvel a causa \xe9 a mesma e vem no caminho do campo; como o campo de grupo n\xe3o admite impedimento, ele \xe9 recusado tamb\xe9m como [campo de grupo com impedimento](/erros/uniplus.grupo_formulario.campo_com_impedimento), na confer\xeancia da forma do grupo. A mensagem \xe9 mostrada ao candidato: escreva o motivo da recusa sem dados pessoais.","Na grava\xe7\xe3o dos itens do formul\xe1rio, esta recusa s\xf3 sai para o item cujo fato existe, \xe9 colet\xe1vel e combina com o tipo de campo: o item com fato [desconhecido](/erros/uniplus.item_formulario.fato_desconhecido), [n\xe3o colet\xe1vel](/erros/uniplus.item_formulario.fato_nao_coletavel) ou com tipo de campo [incoerente](/erros/uniplus.item_formulario.tipo_de_campo_incoerente_com_dominio) \xe9 recusado por essa causa, e o resto da forma dele s\xf3 \xe9 conferido depois que ela for corrigida. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe em `impedimento.mensagem` o texto que explica ao candidato por que a resposta impede a inscri\xe7\xe3o, com at\xe9 500 caracteres."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);